mapper.update:
UPDATE template

SET
title = #{title},
canvas_data = #{canvasData},
updated_at = #{updatedAt}


    , thumbnailpath = #{thumbnailpath}


WHERE id = #{id}

mapper.select:
SELECT a.ClCd, a.ClName, a.PrdnClCd, a.Xpn, a.UseEan, a.ClDv, a.QeeSqo, a.UpdDate, a.Updpn, a.DirPath FROM pppo7010t a
INNER JOIN pppo7000t b ON a.ClCd = b.ClCd AND b.jijumcd = #{jijumcd}
WHERE a.PrdnClCd = #{clcd} AND a.UseEan = 'Y' ORDER BY a.ClCd
